package com.chainauth.blockchain;
import com.chainauth.blockchain.dto.IdentityRegistrationRequest; import com.chainauth.blockchain.dto.IdentityRoleRequest; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.Map;
@RestController @RequestMapping("/api/admin/identity-sync") @PreAuthorize("hasRole('ADMIN')") public class IdentitySyncController {
 private final IdentitySyncService sync; private final IdentityReconciliationService reconciliation; public IdentitySyncController(IdentitySyncService sync, IdentityReconciliationService reconciliation){this.sync=sync;this.reconciliation=reconciliation;}
 @PostMapping("/registrations") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,Object> enqueue(@Valid @RequestBody IdentityRegistrationRequest body,@RequestHeader(value="Idempotency-Key",required=false) String key){try{IdentitySyncJob j=sync.enqueueRegistration(body.address(),body.role(),key);return Map.of("job",j,"accepted",true,"message","Registration queued; privileges must not be granted until status is CONFIRMED");}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PostMapping("/wallets/{address}/role") @ResponseStatus(HttpStatus.ACCEPTED) public Object assignRole(@PathVariable String address,@Valid @RequestBody IdentityRoleRequest body,@RequestHeader(value="Idempotency-Key",required=false) String key){try{return Map.of("job",sync.enqueueRoleChange(address,body.role(),key));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PostMapping("/wallets/{address}/deactivate") @ResponseStatus(HttpStatus.ACCEPTED) public Object deactivate(@PathVariable String address,@RequestHeader(value="Idempotency-Key",required=false) String key){try{return Map.of("job",sync.enqueueStatusChange(address,false,key));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PostMapping("/wallets/{address}/reactivate") @ResponseStatus(HttpStatus.ACCEPTED) public Object reactivate(@PathVariable String address,@RequestHeader(value="Idempotency-Key",required=false) String key){try{return Map.of("job",sync.enqueueStatusChange(address,true,key));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @GetMapping("/reconcile") public Object reconcile(){return reconciliation.reconcile();}
 @GetMapping public Object list(){return sync.list();}
 @PostMapping("/{id}/retry") public Object retry(@PathVariable String id){try{return sync.retry(id);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
 @GetMapping("/{id}") public Object get(@PathVariable String id){try{return sync.get(id);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage());}}
}
